import "./App.css";

function App() {
  return (
    <div className="card">
      <Avatar src="Abdallah.jpg" alt="Abdallah" />
    </div>
  );
}

function Avatar(props) {
  return <img src={props.src} alt={props.alt} />;
}

export default App;
